using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace FortsStudio {
 public partial class Preview:Panel {
  Project currentProject;Entity currentSelected;int buildProgress=100;
  public Project Project {get{return currentProject;}set{if(System.Object.ReferenceEquals(currentProject,value))return;currentProject=value;cameraProject=null;ClearProjectileSprites();DiscardSceneCache();SceneChanged();}}
  public Entity Selected {get{return currentSelected;}set{if(System.Object.ReferenceEquals(currentSelected,value))return;currentSelected=value;sceneDataDirty=true;objectSceneDirty=true;Invalidate();}}
  public int BuildProgress {get{return buildProgress;}set{if(buildProgress==value)return;buildProgress=value;objectSceneDirty=true;Invalidate();}}
  public string Material="",Tool="Балка";public Action Changed,AimChanged;
  public string Notice="Колесо — масштаб · средняя кнопка — сдвиг · Esc — отменить балку";
  float zoom=.85f;PointF camera=new PointF(35,70),cursor,panStart;bool panning=false,paused=false;PointF? start=null;Timer timer=new Timer();Stopwatch clock=Stopwatch.StartNew();double previous=0,sim=0,reloadUntil=0,lastShot=-10;Project cameraProject;
  class Shot {public PointF Position,Previous,Velocity;public double Age,Life;public Entity Projectile;}
  class Burst {public Entity Weapon,Projectile;public PointF Origin;public double Next;public int Left;}
  class Snapshot {public List<Segment> Scene;public List<PlacedItem> Items;}
  List<Shot> shots=new List<Shot>();List<Burst> bursts=new List<Burst>();Stack<Snapshot> undo=new Stack<Snapshot>(),redo=new Stack<Snapshot>();Dictionary<string,Entity> stock=new Dictionary<string,Entity>();
  public Preview(){DoubleBuffered=true;BackColor=Theme.Bg;Dock=DockStyle.Fill;MinimumSize=new Size(250,220);TabStop=true;timer.Interval=16;timer.Tick+=(s,e)=>Step();MouseDown+=Down;MouseMove+=PointerMove;MouseUp+=(s,e)=>panning=false;MouseWheel+=Wheel;KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape){start=null;Invalidate();}if(e.Control&&e.KeyCode==Keys.Z){Undo();e.Handled=true;}if(e.Control&&e.KeyCode==Keys.Y){Redo();e.Handled=true;}};VisibleChanged+=(s,e)=>UpdateAnimationTimer();ParentChanged+=(s,e)=>UpdateAnimationTimer();}
  void UpdateAnimationTimer(){if(Visible&&Parent!=null&&FindForm()!=null){previous=clock.Elapsed.TotalSeconds;timer.Start();}else timer.Stop();}
  public Entity Resolve(string key,string kind="materials"){if(Project==null)return null;EnsureEntityIndex();Entity e;if(entitiesByKind.TryGetValue(kind+"\0"+(key??""),out e))return e;string id=Project.GameRoot+"|"+kind+"|"+key;if(stock.TryGetValue(id,out e))return e;var t=Catalog.Templates.FirstOrDefault(x=>x.Kind==kind&&x.Key==key);if(t==null)return null;e=Catalog.Create(kind,key,Project.GameRoot);e.Key=key;e.NameRu=t.Name;stock[id]=e;return e;}
  float Unit {get{return Project==null?50:(float)Project.Preview.GridUnits;}}
  PointF ToWorld(Point p){return new PointF((p.X-camera.X)/zoom/Unit,(p.Y-camera.Y)/zoom/Unit);}
  PointF Screen(PointF p){return new PointF(camera.X+p.X*Unit*zoom,camera.Y+p.Y*Unit*zoom);}
  PointF Snap(PointF p){EnsureSceneData();PointF closest=p;float best=Single.MaxValue;foreach(var node in sceneJoints){if(node.Team!=Project.Preview.BuildTeam)continue;float dx=node.Point.X-p.X,dy=node.Point.Y-p.Y,d=dx*dx+dy*dy;if(d<best){best=d;closest=node.Point;}}float radius=12/(Unit*zoom);if(best<radius*radius)return closest;return new PointF((float)Math.Round(p.X*4)/4,(float)Math.Round(p.Y*4)/4);}
  static PointF Sub(PointF a,PointF b){return new PointF(a.X-b.X,a.Y-b.Y);}static float Length(PointF a){return (float)Math.Sqrt(a.X*a.X+a.Y*a.Y);}
  public static float Distance(PointF p,PointF a,PointF b){PointF d=Sub(b,a);float l=d.X*d.X+d.Y*d.Y;float t=l==0?0:Math.Max(0,Math.Min(1,((p.X-a.X)*d.X+(p.Y-a.Y)*d.Y)/l));return Length(new PointF(p.X-a.X-t*d.X,p.Y-a.Y-t*d.Y));}
  Snapshot SceneSnapshot(){return new Snapshot{Scene=Project.Scene.Select(x=>new Segment{X1=x.X1,Y1=x.Y1,X2=x.X2,Y2=x.Y2,Material=x.Material,Team=x.Team}).ToList(),Items=Project.Placed.Select(x=>new PlacedItem{X=x.X,Y=x.Y,Entity=x.Entity,Flipped=x.Flipped}).ToList()};}
  void SaveUndo(){undo.Push(SceneSnapshot());if(undo.Count>80){var keep=undo.Take(80).Reverse().ToArray();undo.Clear();foreach(var x in keep)undo.Push(x);}redo.Clear();}
  void Restore(Snapshot s){Project.Scene=s.Scene;Project.Placed=s.Items;start=null;Reset();Notify();}
  public void Undo(){if(Project==null||undo.Count==0)return;redo.Push(SceneSnapshot());Restore(undo.Pop());}
  public void Redo(){if(Project==null||redo.Count==0)return;undo.Push(SceneSnapshot());Restore(redo.Pop());}
  void Notify(){SceneChanged();if(Changed!=null)Changed();}
  void Down(object sender,MouseEventArgs e){Focus();if(Project==null)return;if(e.Button==MouseButtons.Middle){panning=true;panStart=e.Location;return;}if(e.Button==MouseButtons.Right){start=null;Invalidate();return;}if(e.Button!=MouseButtons.Left)return;PointF p=Snap(ToWorld(e.Location));
   if(Tool=="Прицел"){Aim(p);return;}if(Tool=="Стереть"){var obj=Project.Placed.OrderBy(x=>Length(Sub(new PointF(x.X,x.Y),p))).FirstOrDefault();if(obj!=null&&Length(Sub(new PointF(obj.X,obj.Y),p))<.7){SaveUndo();Project.Placed.Remove(obj);Notify();return;}var link=Project.Scene.OrderBy(x=>Distance(p,new PointF(x.X1,x.Y1),new PointF(x.X2,x.Y2))).FirstOrDefault();if(link!=null&&Distance(p,new PointF(link.X1,link.Y1),new PointF(link.X2,link.Y2))*Unit*zoom<12){SaveUndo();Project.Scene.Remove(link);Notify();}return;}
   if(Tool=="Объект"){if(Selected==null||(Selected.Kind!="weapons"&&Selected.Kind!="devices")){Notice="Выберите сооружение или орудие в списке слева.";Invalidate();return;}var support=Project.Scene.Where(x=>x.Team==Project.Preview.BuildTeam&&Math.Abs(x.Y1-x.Y2)<.1).OrderBy(x=>Distance(p,new PointF(x.X1,x.Y1),new PointF(x.X2,x.Y2))).FirstOrDefault();if(support==null||Distance(p,new PointF(support.X1,support.Y1),new PointF(support.X2,support.Y2))>.55){Notice="Объекту нужна горизонтальная балка. Нажмите на её середину.";Invalidate();return;}var material=Resolve(support.Material);if(material!=null&&material.Flags.ContainsKey("SupportsDevices")&&!material.Flags["SupportsDevices"]){Notice="Этот материал не поддерживает сооружения.";Invalidate();return;}float placeX=Math.Max(Math.Min(support.X1,support.X2)+.1f,Math.Min(Math.Max(support.X1,support.X2)-.1f,p.X));if(Project.Placed.Any(a=>Math.Abs(a.X-placeX)<.6&&Math.Abs(a.Y-support.Y1)<.2)){Notice="Платформа занята.";Invalidate();return;}SaveUndo();Project.Placed.Add(new PlacedItem{Entity=Selected.Key,X=placeX,Y=support.Y1});Notice="Объект установлен на платформу.";Notify();return;}
   if(start==null){start=p;Notice="Выберите второй узел · Esc — отменить";}else{PointF a=start.Value;if(Length(Sub(p,a))<.1)return;var mat=Resolve(Material);double len=Length(Sub(p,a))*Unit;bool existingA=Project.Scene.Any(z=>z.Team==Project.Preview.BuildTeam&&(Length(Sub(a,new PointF(z.X1,z.Y1)))<.01||Length(Sub(a,new PointF(z.X2,z.Y2)))<.01)),existingB=Project.Scene.Any(z=>z.Team==Project.Preview.BuildTeam&&(Length(Sub(p,new PointF(z.X1,z.Y1)))<.01||Length(Sub(p,new PointF(z.X2,z.Y2)))<.01));double min=mat==null?37.5:mat.V("MinLength",37.5),max=mat==null?150:mat.V(existingA&&existingB?"MaxLinkLength":"MaxLength",150);if(len<min-.01||len>max+.01){Notice="Длина "+len.ToString("0.#")+"; допустимо "+min.ToString("0.#")+"–"+max.ToString("0.#")+". Измените длину или материал.";Invalidate();return;}if(Project.Scene.Any(x=>Distance(a,new PointF(x.X1,x.Y1),new PointF(x.X2,x.Y2))<.01&&Distance(p,new PointF(x.X1,x.Y1),new PointF(x.X2,x.Y2))<.01)){Notice="Такое соединение уже существует.";return;}SaveUndo();Project.Scene.Add(new Segment{X1=a.X,Y1=a.Y,X2=p.X,Y2=p.Y,Material=Material,Team=Project.Preview.BuildTeam});start=(ModifierKeys&Keys.Shift)!=0?(PointF?)p:null;Notice="Балка: "+len.ToString("0.#")+" ед. · Shift — непрерывная стройка";Notify();}Invalidate();
  }
  void PointerMove(object sender,MouseEventArgs e){if(Project==null)return;bool moved=panning;if(panning){camera.X+=e.X-panStart.X;camera.Y+=e.Y-panStart.Y;panStart=e.Location;}var point=Snap(ToWorld(e.Location));bool changed=point!=cursor;cursor=point;if(Tool=="Прицел"&&(e.Button&MouseButtons.Left)!=0)Aim(cursor);if(moved||changed&&(start!=null||Tool=="Балка"||Tool=="Прицел"))Invalidate();}
  void Wheel(object sender,MouseEventArgs e){var before=ToWorld(e.Location);zoom=Math.Max(.12f,Math.Min(4,zoom*(e.Delta>0?1.15f:1/1.15f)));camera=new PointF(e.X-before.X*Unit*zoom,e.Y-before.Y*Unit*zoom);Invalidate();}
  public void Fit(){if(Project==null)return;var points=Project.Scene.SelectMany(x=>new[]{new PointF(x.X1,x.Y1),new PointF(x.X2,x.Y2)}).Concat(Project.Placed.Select(x=>new PointF(x.X,x.Y))).ToList();if(points.Count==0){zoom=.85f;camera=new PointF(40,90);Invalidate();return;}float l=points.Min(x=>x.X)-1,r=points.Max(x=>x.X)+1,t=points.Min(x=>x.Y)-3,b=points.Max(x=>x.Y)+1;zoom=Math.Max(.12f,Math.Min(2,Math.Min((Width-60)/(r-l)/Unit,(Height-95)/(b-t)/Unit)));camera=new PointF(30-l*Unit*zoom,62-t*Unit*zoom);Invalidate();}
  public void Clear(){if(Project==null)return;SaveUndo();Project.Scene.Clear();Project.Placed.Clear();start=null;Reset();Notify();}
  public void Reset(){shots.Clear();bursts.Clear();sim=0;reloadUntil=0;lastShot=-10;paused=false;previous=clock.Elapsed.TotalSeconds;if(Project!=null&&Project.Preview.FollowProjectile)Fit();Invalidate();}
  public void PauseAnimation(){paused=!paused;Notice=paused?"Анимация на паузе":"Анимация продолжена";Invalidate();}
  void Aim(PointF p){var origin=Origin();Project.Preview.AimDegrees=Math.Max(-89,Math.Min(89,-Math.Atan2(p.Y-origin.Y,p.X-origin.X)*180/Math.PI));if(AimChanged!=null)AimChanged();Notify();}
  Entity Weapon(){if(Project==null)return null;EnsureEntityIndex();return Selected!=null&&Selected.Kind=="weapons"?Selected:firstWeapon;}
  PointF Origin(){var weapon=Weapon();var item=weapon==null?null:Project.Placed.FirstOrDefault(x=>x.Entity==weapon.Key);if(weapon!=null&&weapon.Art!=null&&weapon.Art.Enabled){var pos=item==null?new PointF(4,4):new PointF(item.X,item.Y);return new PointF(pos.X+(float)weapon.Art.MountX/Unit,pos.Y-(float)weapon.Art.MountY/Unit);}return item==null?new PointF(4,4):new PointF(item.X,item.Y-.7f);}
  public void Fire(){if(Project==null)return;var w=Weapon();if(w==null){Notice="Создайте орудие.";return;}if(Project.Preview.AimDegrees<w.V("MinFireAngle",-89)||Project.Preview.AimDegrees>w.V("MaxFireAngle",89)){Notice="Угол вне диапазона орудия: "+w.V("MinFireAngle",-89)+"…"+w.V("MaxFireAngle",89)+"°";Invalidate();return;}if(sim<reloadUntil){Notice="Перезарядка: "+(reloadUntil-sim).ToString("0.0")+" с";return;}string ammo=w.Ammo.Contains(Project.Preview.Ammo)?Project.Preview.Ammo:w.Ammo.FirstOrDefault();var projectile=Resolve(ammo??"cannon","projectiles");if(projectile==null)return;int rounds=Math.Max(1,Math.Min(1000,(int)w.V("RoundsEachBurst",1)));bursts.Add(new Burst{Weapon=w,Projectile=projectile,Origin=Origin(),Next=sim,Left=rounds});reloadUntil=sim+w.V("ReloadTime",1)+Math.Max(0,rounds-1)*w.V("RoundPeriod",.1);paused=false;Notice="Эскиз выстрела. Точное поведение — кнопка «Полигон Forts».";Invalidate();}
  void Emit(Burst b){lastShot=sim;int pellets=Math.Max(1,Math.Min(100,(int)b.Weapon.V("ProjectilesEachRound",1)));double angle=Project.Preview.AimDegrees*Math.PI/180,velocity=b.Weapon.V("MinFireSpeed",6000)+(b.Weapon.V("MaxFireSpeed",6000)-b.Weapon.V("MinFireSpeed",6000))*Project.Preview.Power;double spread=b.Weapon.V("FireStdDev",0);for(int i=0;i<pellets&&shots.Count<600;i++){double a=angle+(i-(pellets-1)*.5)*spread;var v=new PointF((float)(Math.Cos(a)*velocity/Unit),(float)(-Math.Sin(a)*velocity/Unit));var origin=ShotOrigin(b.Weapon,b.Origin,a);shots.Add(new Shot{Position=origin,Previous=origin,Velocity=v,Life=b.Projectile.V("MaxAge",30),Projectile=b.Projectile});}}
  void Step(){long calculateStarted=Stopwatch.GetTimestamp();double now=clock.Elapsed.TotalSeconds,elapsed=Math.Min(.1,now-previous);previous=now;if(Project==null||!Visible||Parent==null)return;var host=FindForm();if(host==null||host.WindowState==FormWindowState.Minimized)return;EnsureProjectState();if(paused)return;EnsureSceneData();bool wasMoving=shots.Count>0||bursts.Count>0||sim-lastShot<.4;double dt=elapsed*Project.Preview.TimeScale;sim+=dt;for(int i=bursts.Count-1;i>=0;i--){var b=bursts[i];int count=0;while(sim>=b.Next&&b.Left>0&&count++<16){Emit(b);b.Left--;b.Next+=Math.Max(.001,b.Weapon.V("RoundPeriod",.1));}if(b.Left<=0)bursts.RemoveAt(i);}for(int i=shots.Count-1;i>=0;i--){var shot=shots[i];shot.Age+=dt;shot.Previous=shot.Position;shot.Position=new PointF(shot.Position.X+shot.Velocity.X*(float)dt,shot.Position.Y+shot.Velocity.Y*(float)dt);shot.Velocity.Y+=(float)(981/Unit*dt);if(SplitPreview(shot))continue;if(shot.Age>shot.Life||shot.Age>20||Math.Abs(shot.Position.X)>600||Math.Abs(shot.Position.Y)>600)shots.RemoveAt(i);}if(Project.Preview.FollowProjectile&&shots.Count>0){var lead=shots[0].Position;camera=new PointF(Width*.5f-lead.X*Unit*zoom,Height*.45f-lead.Y*Unit*zoom);}if(wasMoving||shots.Count>0||bursts.Count>0||hasAnimatedModels&&dt>0)Invalidate();simulationMilliseconds=(Stopwatch.GetTimestamp()-calculateStarted)*1000.0/Stopwatch.Frequency;}
  protected override void Dispose(bool disposing){if(disposing){timer.Stop();timer.Dispose();ClearProjectileSprites();DiscardSceneCache();performanceFont.Dispose();}base.Dispose(disposing);}
 }
